<?php
declare(strict_types=1);

function tenant_branches_v1(App $app,int $tenantId,bool $activeOnly=true):array
{
    $rows=$app->all('SELECT * FROM branches WHERE tenant_id=?'.($activeOnly?' AND is_active=1':'').' ORDER BY is_default DESC,name',[$tenantId]);if(!$rows){$tenant=$app->one('SELECT name,whatsapp,phone,address FROM tenants WHERE id=?',[$tenantId]);if($tenant){$app->exec("INSERT IGNORE INTO branches(tenant_id,name,slug,whatsapp,phone,address,is_default,is_active) VALUES(?,?,?,?,?,?,1,1)",[$tenantId,'Sucursal principal','principal',$tenant['whatsapp'],$tenant['phone'],$tenant['address']]);$rows=$app->all('SELECT * FROM branches WHERE tenant_id=?'.($activeOnly?' AND is_active=1':'').' ORDER BY is_default DESC,name',[$tenantId]);}}return $rows;
}

function selected_branch_v1(App $app,array $tenant):array
{
    $branches=tenant_branches_v1($app,(int)$tenant['id']);
    if(!$branches)return [null,[]];
    $requested=trim((string)($_GET['sucursal']??''));$selected=null;
    if($requested!=='')foreach($branches as $branch)if(hash_equals((string)$branch['slug'],$requested)){$selected=$branch;break;}
    if(!$selected&&count($branches)===1)$selected=$branches[0];
    return [$selected,$branches];
}

function adaptive_slide_v1(array $slide,int $index,string $shade='linear-gradient(90deg,#0b1d32cc,#0b7a5566)',string $extra=''):string
{
    $image=public_media_url($slide['image']??null);$content='';
    if(($slide['tag']??'')!=='')$content.='<span class="tag">'.e($slide['tag']).'</span>';
    if(($slide['title']??'')!=='')$content.='<h1>'.e($slide['title']).'</h1>';
    if(($slide['body']??'')!=='')$content.='<p>'.e($slide['body']).'</p>';
    $content.=$extra;
    $src=$index===0?'src="'.e($image).'" fetchpriority="high"':'src="'.url('assets/placeholder.svg').'" data-src="'.e($image).'" loading="lazy"';
    return '<article class="slide adaptive-slide '.($index===0?'active':'').'"><img class="slide-blur" '.$src.' decoding="async" alt="" aria-hidden="true"><img class="slide-image" '.$src.' decoding="async" alt=""><span class="slide-shade" style="background:'.e($shade).'"></span>'.($content!==''?'<div class="slide-content">'.$content.'</div>':'').'</article>';
}

