function cart_drawer_v6(App $app,array $tenant,array $branch):void
{
    $zones=$app->all('SELECT * FROM delivery_zones WHERE tenant_id=? AND is_active=1 ORDER BY name',[$tenant['id']]);$paymentMethods=json_decode((string)($branch['payment_methods']??$tenant['payment_methods']??''),true)?:['SINPE Móvil','Efectivo','Tarjeta al recibir','Transferencia'];$deliveryTypes=json_decode((string)($branch['delivery_types']??$tenant['delivery_types']??''),true)?:['delivery','pickup','coordinated'];$paymentHtml='';foreach($paymentMethods as $method)$paymentHtml.='<option>'.e($method).'</option>';$deliveryHtml='';foreach(['delivery'=>'Delivery','pickup'=>'Recoger en el negocio','coordinated'=>'Envío coordinado'] as $key=>$label)if(in_array($key,$deliveryTypes,true))$deliveryHtml.='<option value="'.$key.'">'.$label.'</option>';
    $user=current_user();$addresses=$user&&$user['role']==='customer'?$app->all('SELECT * FROM customer_addresses WHERE user_id=? ORDER BY is_default DESC,id DESC',[$user['id']]):[];$demoGuest=is_demo_tenant_v12($tenant)&&(!$user||$user['role']!=='customer');
    echo '<aside id="cartDrawer" class="drawer"><div class="drawer-bg" data-close-cart></div><div class="drawer-panel"><div class="drawer-head"><div><small>'.e($branch['name']).'</small><h2>Tu pedido</h2></div><button class="icon-btn" data-close-cart>×</button></div><div id="cartItems"></div><div class="cart-summary"><div class="summary-row"><span>Subtotal estimado</span><strong id="cartSubtotal">₡0,00</strong></div><small class="muted">IVA, descuento y entrega se calculan al confirmar.</small></div><form id="checkoutForm" action="'.url('api/checkout').'">'.csrf_field().'<input type="hidden" name="tenant" value="'.e($tenant['slug']).'"><input type="hidden" name="branch_id" value="'.(int)$branch['id'].'">';if($demoGuest||(!$user&&function_exists('r2_active')&&r2_active($app)))echo '<div class="split">'.field($demoGuest?'Nombre para la demo':'Tu nombre','guest_name',$demoGuest?'Cliente de prueba':'',true).field('Teléfono','guest_phone',$demoGuest?'8888-0000':'',true).'</div>';echo '<div class="form-group"><label>Cédula (opcional)</label><input class="input" name="customer_id_number" maxlength="40"></div><div class="form-group"><label>Forma de pago</label><select class="input" name="payment" required>'.$paymentHtml.'</select></div><div class="form-group"><label>Tipo de entrega</label><select class="input" name="delivery_type">'.$deliveryHtml.'</select></div><div class="form-group"><label>Zona de envío</label><select class="input" name="zone_id"><option value="">Seleccionar</option>';foreach($zones as $zone)echo '<option value="'.(int)$zone['id'].'">'.e($zone['name']).' · '.money((float)$zone['price']).'</option>';echo '</select></div>';if($addresses){echo '<div class="form-group"><label>Dirección guardada</label><select class="input" data-saved-address><option value="">Escribir otra dirección</option>';foreach($addresses as $address)echo '<option value="'.e(json_encode(['address'=>$address['address'],'reference'=>$address['reference']],JSON_HEX_APOS|JSON_HEX_QUOT)).'">'.e($address['label']).' · '.e($address['address']).'</option>';echo '</select></div>';}echo '<div class="form-group"><label>Dirección</label><textarea class="input" name="address" placeholder="Provincia, cantón y distrito"></textarea></div><div class="form-group"><label>Referencia</label><textarea class="input" name="address_reference" placeholder="Señas para llegar"></textarea></div><div class="form-group"><label>Programar pedido (opcional)</label><input class="input" type="datetime-local" name="scheduled_at" min="'.date('Y-m-d\TH:i').'"></div><div class="form-group"><label>Código de descuento o premio</label><input class="input" name="coupon" maxlength="60" placeholder="Cupón o FIEL-XXXXXXXXXX"></div><div class="form-group"><label>Notas</label><textarea class="input" name="notes" placeholder="Detalles para el negocio"></textarea></div><button class="btn btn-accent btn-block" type="submit">Enviar pedido por WhatsApp</button></form></div></aside>';
}


function coupon_preview_api_v1453(App $app):never
{
    if(!is_post())json_response(['ok'=>false],405);
    $raw=json_input_qa();
    $_POST=$raw+$_POST;
    verify_csrf();

    $tenant=tenant_by_slug($app,(string)($raw['tenant']??''));
    if(!$tenant||!$tenant['is_active'])json_response(['ok'=>false,'error'=>'Tienda no disponible.'],404);

    $code=strtoupper(trim((string)($raw['coupon']??'')));
    $subtotal=max(0,(float)($raw['subtotal']??0));
    if($code==='')json_response(['ok'=>true,'valid'=>false,'discount'=>0,'message'=>'']);

    if(str_starts_with($code,'FIEL-')){
        json_response(['ok'=>true,'valid'=>null,'discount'=>0,'message'=>'La recompensa de fidelización se valida al confirmar el pedido.']);
    }

    $coupon=$app->one(
      "SELECT id,code,type,value,min_order,max_uses,uses_count,starts_at,ends_at,is_active
       FROM coupons
       WHERE tenant_id=? AND code=? LIMIT 1",
      [$tenant['id'],$code]
    );

    if(!$coupon||!(int)$coupon['is_active'])
        json_response(['ok'=>true,'valid'=>false,'discount'=>0,'message'=>'Cupón no válido o inactivo.']);

    if($coupon['starts_at']&&strtotime($coupon['starts_at'])>time())
        json_response(['ok'=>true,'valid'=>false,'discount'=>0,'message'=>'Este cupón todavía no está vigente.']);

    if($coupon['ends_at']&&strtotime($coupon['ends_at'])<time())
        json_response(['ok'=>true,'valid'=>false,'discount'=>0,'message'=>'Este cupón ya venció.']);

    if($coupon['max_uses']!==null&&(int)$coupon['uses_count']>=(int)$coupon['max_uses'])
        json_response(['ok'=>true,'valid'=>false,'discount'=>0,'message'=>'Este cupón ya alcanzó su límite de usos.']);

    if($subtotal<(float)$coupon['min_order'])
        json_response(['ok'=>true,'valid'=>false,'discount'=>0,'message'=>'Compra mínima: '.money((float)$coupon['min_order']).'.']);

    $discount=$coupon['type']==='percent'
      ? min($subtotal,round($subtotal*((float)$coupon['value']/100),2))
      : min($subtotal,(float)$coupon['value']);

    json_response([
      'ok'=>true,'valid'=>true,'discount'=>$discount,'code'=>$code,
      'label'=>$coupon['type']==='percent'
        ? rtrim(rtrim(number_format((float)$coupon['value'],2,'.',''),'0'),'.').'% de descuento'
        : money((float)$coupon['value']).' de descuento',
      'message'=>'Cupón aplicado: '.($coupon['type']==='percent'
        ? rtrim(rtrim(number_format((float)$coupon['value'],2,'.',''),'0'),'.').'%'
        : money((float)$coupon['value']))
    ]);
}

function checkout_api_v6(App $app):never
{
    $raw=json_input_qa();$_POST=$raw+$_POST;verify_csrf();$tenant=tenant_by_slug($app,(string)($raw['tenant']??''));if(!$tenant||!$tenant['is_active'])json_response(['ok'=>false,'error'=>'Tienda no disponible.'],404);
    $user=current_user();if(!$user&&function_exists('r2_active')&&r2_active($app)&&!is_demo_tenant_v12($tenant))$user=r2_customer_checkout($app,$tenant,$raw);$isDemo=is_demo_tenant_v12($tenant);if($isDemo&&$user&&$user['role']!=='customer')$user=null;if($user&&$user['role']!=='customer')json_response(['ok'=>false,'error'=>'Para comprar, cierra tu sesión administrativa.'],403);if(!$user&&!$isDemo){$next=safe_next_url_v1($app,(string)($_SERVER['HTTP_REFERER']??''));json_response(['ok'=>false,'login'=>url('login'.($next?'?next='.rawurlencode($next):''))],401);}if(!$user){$user=$app->one("SELECT * FROM users WHERE email='cliente.demo@fisitaap.com' AND role='customer' AND is_active=1 LIMIT 1");if(!$user)json_response(['ok'=>false,'error'=>'El comprador técnico de la demo no está disponible. Ejecuta nuevamente la actualización.'],500);$user['name']=trim(substr(strip_tags((string)($raw['guest_name']??'Cliente de prueba')),0,150))?:'Cliente de prueba';$user['phone']=trim(substr(strip_tags((string)($raw['guest_phone']??'8888-0000')),0,40))?:'8888-0000';}
    if(!rate_limit_persistent($app,'checkout',client_identity((string)$user['id']),10,300))json_response(['ok'=>false,'error'=>'Demasiados intentos. Espera unos minutos.'],429);
    $phoneDigits=preg_replace('/\D+/','',(string)($user['phone']??''));if(!preg_match('/^(?:[0-9]{8}|506[0-9]{8})$/',$phoneDigits))json_response(['ok'=>false,'error'=>'Escribe un teléfono de Costa Rica de 8 dígitos, con 506 opcional.'],422);
    $branches=tenant_branches_v1($app,(int)$tenant['id']);$branchId=(int)($raw['branch_id']??0);$branch=null;foreach($branches as $candidate)if((int)$candidate['id']===$branchId){$branch=$candidate;break;}if(!$branch&&count($branches)===1)$branch=$branches[0];if(!$branch)json_response(['ok'=>false,'error'=>'Selecciona una sucursal válida.'],422);$branchId=(int)$branch['id'];
