function tenant_branches_admin_v1(App $app,array $user,array $tenant):void
{
    if($user['role']!=='tenant_admin'&&restructure_can_r1($app,$user,'sucursales')!==true){http_response_code(403);simple_error('Acceso restringido','No tienes permiso para sucursales.');return;}
    if(is_post()){
        verify_csrf();$action=(string)($_POST['action']??'save_branch');
        try{
            if($action==='save_branch'){$id=(int)($_POST['id']??0);$name=trim((string)($_POST['name']??''));$slug=slugify((string)(($_POST['slug']??'')?:$name));if($name===''||$slug==='')throw new RuntimeException('Escribe el nombre de la sucursal.');$duplicate=$app->one('SELECT id FROM branches WHERE tenant_id=? AND slug=? AND id<>?',[$tenant['id'],$slug,$id]);if($duplicate)throw new RuntimeException('Ya existe una sucursal con ese enlace.');$values=[$name,$slug,trim((string)($_POST['whatsapp']??'')),trim((string)($_POST['phone']??'')),trim((string)($_POST['address']??'')),isset($_POST['is_active'])?1:0];if($id)$app->exec('UPDATE branches SET name=?,slug=?,whatsapp=?,phone=?,address=?,is_active=? WHERE id=? AND tenant_id=?',array_merge($values,[$id,$tenant['id']]));else{$isDefault=$app->one('SELECT id FROM branches WHERE tenant_id=?',[$tenant['id']])?0:1;$app->exec('INSERT INTO branches(tenant_id,name,slug,whatsapp,phone,address,is_active,is_default) VALUES(?,?,?,?,?,?,?,?)',array_merge([$tenant['id']],$values,[$isDefault]));}flash('success','Sucursal guardada.');}
            elseif($action==='toggle'){$app->exec('UPDATE branches SET is_active=1-is_active WHERE id=? AND tenant_id=? AND is_default=0',[(int)$_POST['id'],$tenant['id']]);flash('success','Estado actualizado.');}
            elseif($action==='default'){$id=(int)$_POST['id'];if(!$app->one('SELECT id FROM branches WHERE id=? AND tenant_id=?',[$id,$tenant['id']]))throw new RuntimeException('Sucursal inválida.');$app->db->beginTransaction();$app->exec('UPDATE branches SET is_default=0 WHERE tenant_id=?',[$tenant['id']]);$app->exec('UPDATE branches SET is_default=1,is_active=1 WHERE id=? AND tenant_id=?',[$id,$tenant['id']]);$app->db->commit();flash('success','Sucursal principal actualizada.');}
            elseif($action==='mode'){$mode=($_POST['catalog_mode']??'global')==='branches'?'branches':'global';if($mode==='branches'&&($tenant['catalog_mode']??'global')!=='branches')$app->exec('INSERT IGNORE INTO branch_products(branch_id,product_id,is_active) SELECT b.id,p.id,1 FROM branches b JOIN products p ON p.tenant_id=b.tenant_id WHERE b.tenant_id=?',[$tenant['id']]);$app->exec('UPDATE tenants SET catalog_mode=? WHERE id=?',[$mode,$tenant['id']]);flash('success',$mode==='global'?'Todas las sucursales usan el catálogo global.':'Catálogos independientes activados.');}
