            elseif($action==='copy_catalog'){$source=(int)$_POST['source_branch'];$target=(int)$_POST['target_branch'];if($source===$target)throw new RuntimeException('Elige sucursales diferentes.');foreach([$source,$target] as $id)if(!$app->one('SELECT id FROM branches WHERE id=? AND tenant_id=?',[$id,$tenant['id']]))throw new RuntimeException('Sucursal inválida.');$app->db->beginTransaction();if(($tenant['catalog_mode']??'global')!=='branches')$app->exec('INSERT IGNORE INTO branch_products(branch_id,product_id,is_active) SELECT ?,id,1 FROM products WHERE tenant_id=?',[$source,$tenant['id']]);$app->exec('DELETE FROM branch_products WHERE branch_id=?',[$target]);$app->exec('INSERT INTO branch_products(branch_id,product_id,price_override,sale_price_override,is_active) SELECT ?,product_id,price_override,sale_price_override,is_active FROM branch_products WHERE branch_id=?',[$target,$source]);$app->exec("DELETE FROM tenant_content WHERE tenant_id=? AND branch_id=? AND section_key IN ('home_slider','catalog_slider','home_block')",[$tenant['id'],$target]);$app->exec("INSERT INTO tenant_content(tenant_id,branch_id,section_key,title,body,image,button_text,button_url,sort_order,is_active) SELECT tenant_id,?,section_key,title,body,image,button_text,button_url,sort_order,is_active FROM tenant_content WHERE tenant_id=? AND branch_id=? AND section_key IN ('home_slider','catalog_slider','home_block')",[$target,$tenant['id'],$source]);$app->exec("UPDATE tenants SET catalog_mode='branches' WHERE id=?",[$tenant['id']]);$app->db->commit();flash('success','Catálogo, precios y promociones copiados.');}
