    admin_shell_start('Sucursales y catálogos',$user,$tenant,'sucursales');echo '<section class="card admin-card"><div class="section-head"><div><span class="tag">MULTI SUCURSAL</span><h2>Funcionamiento del catálogo</h2><p class="muted">En modo global todas las sucursales comparten productos. En modo independiente eliges productos y precios para cada una.</p></div><form method="post">'.csrf_field().'<input type="hidden" name="action" value="mode"><select class="input" name="catalog_mode"><option value="global">Catálogo global</option><option value="branches" '.(($tenant['catalog_mode']??'global')==='branches'?'selected':'').'>Catálogos independientes</option></select><button class="btn">Guardar modo</button></form></div></section><div class="split" style="margin-top:20px"><section class="card admin-card"><h2>'.($edit?'Editar':'Nueva').' sucursal</h2><form method="post">'.csrf_field().'<input type="hidden" name="action" value="save_branch"><input type="hidden" name="id" value="'.(int)($edit['id']??0).'">'.field('Nombre','name',$edit['name']??'',true).field('Enlace corto','slug',$edit['slug']??'').field('WhatsApp de pedidos','whatsapp',$edit['whatsapp']??$tenant['whatsapp'],true).field('Teléfono','phone',$edit['phone']??$tenant['phone']).'<div class="form-group"><label>Dirección</label><textarea class="input" name="address">'.e($edit['address']??$tenant['address']).'</textarea></div><label><input type="checkbox" name="is_active" '.(!isset($edit['is_active'])||$edit['is_active']?'checked':'').'> Sucursal activa</label><button class="btn btn-block" style="margin-top:15px">Guardar sucursal</button></form></section><section class="card admin-card"><h2>Sucursales</h2>';foreach($branches as $branch)echo '<article class="branch-admin-row"><div><strong>'.e($branch['name']).'</strong> '.($branch['is_default']?'<span class="tag">PRINCIPAL</span>':'').'<small>'.e($branch['address']).' · '.e($branch['whatsapp']).'</small></div><div><a class="btn btn-light" href="?edit='.(int)$branch['id'].'">Editar</a> <a class="btn btn-light" href="?branch='.(int)$branch['id'].'">Catálogo</a> <a class="btn btn-light" href="'.url('admin/sucursal-detalle?branch_id='.(int)$branch['id']).'">Horario, pago y entrega</a>'.(!$branch['is_default']?'<form method="post" class="inline-form">'.csrf_field().'<input type="hidden" name="id" value="'.(int)$branch['id'].'"><button class="btn btn-light" name="action" value="default">Hacer principal</button><button class="btn btn-light" name="action" value="toggle">'.($branch['is_active']?'Desactivar':'Activar').'</button></form>':'').'</div></article>';echo '</section></div>';
