    if($activeBranch&&($tenant['catalog_mode']??'global')==='branches'){echo '<section class="card admin-card" style="margin-top:20px"><div class="section-head"><div><span class="tag">CATÁLOGO INDEPENDIENTE</span><h2>'.e(array_column($branches,'name','id')[$activeBranch]??'Sucursal').'</h2><p class="muted">Marca los productos disponibles. Los precios vacíos utilizan el precio general.</p></div></div><form method="post">'.csrf_field().'<input type="hidden" name="action" value="save_catalog"><input type="hidden" name="branch_id" value="'.$activeBranch.'"><div class="branch-product-list">';foreach($products as $product){$row=$assigned[(int)$product['id']]??null;echo '<label class="branch-product-row"><input type="checkbox" name="products[]" value="'.(int)$product['id'].'" '.($row?'checked':'').'><span><strong>'.e($product['name']).'</strong><small>'.e($product['category']??'Sin categoría').' · General '.money((float)$product['price']).'</small></span><input class="input compact" type="number" step="0.01" min="0" name="price_override['.(int)$product['id'].']" value="'.e($row['price_override']??'').'" placeholder="Precio propio"><input class="input compact" type="number" step="0.01" min="0" name="sale_override['.(int)$product['id'].']" value="'.e($row['sale_price_override']??'').'" placeholder="Promo propia"></label>';}echo '</div><button class="btn">Guardar catálogo de esta sucursal</button></form></section>';}
