class="btn btn-light" name="action" value="toggle">'.($row['is_active']?'Desactivar':'Activar').'</button><button class="btn btn-danger" name="action" value="delete" onclick="return confirm(\'¿Eliminar esta categoría?\')">Eliminar</button></form></div></article>';echo '</section></div>';admin_shell_end();
}

