</section><section class="card admin-card"><h2>Contenido actual</h2>';foreach($rows as $row)echo '<article class="content-admin-row">'.($row['image']?'<img src="'.e(public_media_url($row['image'])).'" alt="">':'').'<div><span class="tag">'.e($row['section_key']).'</span><strong>'.e($row['title']).'</strong><small>'.e($row['branch_name']?'Solo '.$row['branch_name']:'Global · todas las sucursales').'</small><a class="btn btn-light" href="?edit='.(int)$row['id'].'">Editar</a><form method="post" class="inline-form">'.csrf_field().'<input type="hidden" name="id" value="'.(int)$row['id'].'"><button class="btn btn-light" name="action" value="toggle">'.($row['is_active']?'Desactivar':'Activar').'</button><button class="btn btn-danger" name="action" value="delete" onclick="return confirm(\'¿Eliminar este contenido?\')">Eliminar</button></form></div></article>';echo '</section></div>';admin_shell_end();
}

function master_reports_v2_no_demo(App $app,array $user):void
{
    [$from,$to]=valid_report_dates_v1();$rows=$app->all("SELECT t.name,t.plan,t.expires_at,COUNT(o.id) orders_count,COALESCE(SUM(CASE WHEN o.status!='cancelled' THEN o.total ELSE 0 END),0) sales,COUNT(DISTINCT o.user_id) customers FROM tenants t LEFT JOIN orders o ON o.tenant_id=t.id AND DATE(o.created_at) BETWEEN ? AND ? WHERE t.slug NOT IN ('tienda-demo','restaurante-demo') GROUP BY t.id ORDER BY sales DESC",[$from,$to]);if(($_GET['export']??'')==='csv')csv_download_v1('reporte-global-fisitapp.csv',['Empresa','Plan','Vence','Pedidos','Ventas','Clientes'],$rows);admin_shell_start('Reportes globales',$user,null,'reportes');echo '<form class="card admin-card" method="get"><div class="split">'.field('Desde','from',$from,true,'date').field('Hasta','to',$to,true,'date').'</div><button class="btn">Filtrar</button> <a class="btn btn-light" href="?from='.e($from).'&to='.e($to).'&export=csv">Exportar CSV</a></form>';report_table_v1('Rendimiento por empresa',$rows,['name'=>'Empresa','plan'=>'Plan','expires_at'=>'Vence','orders_count'=>'Pedidos','sales'=>'Ventas','customers'=>'Clientes'],['sales']);admin_shell_end();
}

function master_commercial_v2_no_demo(App $app,array $user):void
{
    if(is_post()){verify_csrf();$plan=trim((string)$_POST['plan']);$expires=trim((string)($_POST['expires_at']??''));$app->exec("UPDATE tenants SET plan=?,expires_at=?,is_active=? WHERE id=? AND slug NOT IN ('tienda-demo','restaurante-demo')",[$plan?:'Profesional',$expires?:null,isset($_POST['is_active'])?1:0,(int)$_POST['id']]);flash('success','Plan actualizado.');redirect(url('master/planes'));}$rows=$app->all("SELECT t.*,(SELECT COUNT(*) FROM users u WHERE u.tenant_id=t.id) users_count,(SELECT COUNT(*) FROM products p WHERE p.tenant_id=t.id) products_count,(SELECT COUNT(*) FROM orders o WHERE o.tenant_id=t.id) orders_count FROM tenants t WHERE t.slug NOT IN ('tienda-demo','restaurante-demo') ORDER BY t.name");admin_shell_start('Planes y vencimientos',$user,null,'planes');echo '<section class="card admin-card"><div class="table-wrap"><table class="table"><tr><th>Empresa</th><th>Uso</th><th>Plan y vencimiento</th><th>Estado</th></tr>';foreach($rows as $row)echo '<tr><td><strong>'.e($row['name']).'</strong><br>/'.e($row['slug']).'</td><td>'.e($row['users_count']).' usuarios<br>'.e($row['products_count']).' productos<br>'.e($row['orders_count']).' pedidos</td><td><form method="post">'.csrf_field().'<input type="hidden" name="id" value="'.(int)$row['id'].'"><input class="input compact" name="plan" value="'.e($row['plan']).'" required><input class="input compact" type="date" name="expires_at" value="'.e($row['expires_at']).'"><label><input type="checkbox" name="is_active" '.($row['is_active']?'checked':'').'> Activa</label><button class="btn btn-light">Guardar</button></form></td><td><span class="status '.(!$row['is_active']?'status-off':'').'">'.($row['is_active']?'Activa':'Suspendida').'</span></td></tr>';echo '</table></div></section>';admin_shell_end();
}

function tenant_orders_v6(App $app,array $user,array $tenant):void
{
    if(!empty($_GET['view'])){tenant_orders_v3($app,$user,$tenant);return;}if(is_post()){verify_csrf();$status=(string)($_POST['status']??'');if(in_array($status,['new','confirmed','preparing','ready','sent','delivered','cancelled'],true)){$orderId=(int)$_POST['id'];order_status_qa($app,(int)$tenant['id'],$orderId,$status,(int)$user['id']);if($status==='delivered'&&function_exists('loyalty_sync_order_v12'))loyalty_sync_order_v12($app,$orderId);audit($app,$tenant['id'],$user['id'],'update_order','order',$orderId);flash('success','Pedido actualizado.');}redirect(url('admin/pedidos'));}
    $status=(string)($_GET['status']??'');$branchId=(int)($_GET['branch']??0);$params=[$tenant['id']];$sql='SELECT o.*,b.name branch_name FROM orders o LEFT JOIN branches b ON b.id=o.branch_id WHERE o.tenant_id=?';if(in_array($status,['new','confirmed','preparing','ready','sent','delivered','cancelled'],true)){$sql.=' AND o.status=?';$params[]=$status;}else $status='';if($branchId){$sql.=' AND o.branch_id=?';$params[]=$branchId;}$sql.=' ORDER BY o.created_at DESC LIMIT 300';$rows=$app->all($sql,$params);$branches=tenant_branches_v1($app,(int)$tenant['id'],false);
    admin_shell_start('Pedidos por sucursal',$user,$tenant,'pedidos');echo '<form class="card admin-card report-filter" method="get"><div class="split"><div class="form-group"><label>Estado</label><select class="input" name="status"><option value="">Todos</option>';foreach(['new'=>'Nuevos','confirmed'=>'Confirmados','preparing'=>'Preparando','ready'=>'Listos','sent'=>'Enviados','delivered'=>'Entregados','cancelled'=>'Cancelados'] as $key=>$label)echo '<option value="'.$key.'" '.($status===$key?'selected':'').'>'.$label.'</option>';echo '</select></div><div class="form-group"><label>Sucursal</label><select class="input" name="branch"><option value="0">Todas</option>';foreach($branches as $branch)echo '<option value="'.(int)$branch['id'].'" '.($branchId==(int)$branch['id']?'selected':'').'>'.e($branch['name']).'</option>';echo '</select></div></div><button class="btn">Filtrar</button></form><section class="card admin-card" style="margin-top:18px"><div class="table-wrap"><table class="table"><tr><th>Pedido</th><th>Sucursal</th><th>Cliente</th><th>Total</th><th>Pago</th><th>Estado</th><th>Fecha</th><th></th></tr>';foreach($rows as $order)echo '<tr><td>#'.e($order['order_number']).'</td><td>'.e($order['branch_name']??'Principal').'</td><td>'.e($order['customer_name']).'<br><small>'.e($order['customer_phone']).'</small></td><td>'.money((float)$order['total']).'</td><td>'.e($order['payment_method']).'</td><td><form method="post">'.csrf_field().'<input type="hidden" name="id" value="'.(int)$order['id'].'"><select class="input" name="status" onchange="this.form.submit()">'.implode('',array_map(fn($key,$label)=>'<option value="'.$key.'" '.($order['status']===$key?'selected':'').'>'.$label.'</option>',array_keys(['new'=>'Nuevo','confirmed'=>'Confirmado','preparing'=>'Preparando','ready'=>'Listo','sent'=>'Enviado','delivered'=>'Entregado','cancelled'=>'Cancelado']),array_values(['new'=>'Nuevo','confirmed'=>'Confirmado','preparing'=>'Preparando','ready'=>'Listo','sent'=>'Enviado','delivered'=>'Entregado','cancelled'=>'Cancelado']))).'</select></form></td><td>'.e(date('d/m/Y H:i',strtotime($order['created_at']))).'</td><td><a class="btn btn-light" href="?view='.(int)$order['id'].'">Detalle</a> <a class="btn btn-light" href="'.url('admin/recibo?pedido='.(int)$order['id']).'">Comanda Print</a></td></tr>';if(!$rows)echo '<tr><td colspan="8">No hay pedidos para el filtro seleccionado.</td></tr>';echo '</table></div></section>';admin_shell_end();
}
